<script setup>
import {ref} from 'vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({accesses:Object,students:Array,exams:Array,filters:Object,today:String});const {context,base}=useExamContext();const open=ref(false),editing=ref(null),action=ref(null);const search=ref(props.filters.search||''),date=ref(props.filters.date||'');const form=useForm({user_id:'',exam_id:'',access_mode:'day',session_name:'',exam_date:props.today,start_time:'08:00',end_time:'10:00',max_attempts:1,is_active:true});
function show(access=null){editing.value=access;form.clearErrors();Object.assign(form,access?{user_id:access.user_id,exam_id:access.exam_id,access_mode:access.access_mode,session_name:access.session_name||'',exam_date:access.exam_date.slice(0,10),start_time:access.start_time?.slice(0,5)||'08:00',end_time:access.end_time?.slice(0,5)||'10:00',max_attempts:access.max_attempts,is_active:access.is_active}:{user_id:'',exam_id:'',access_mode:'day',session_name:'',exam_date:props.today,start_time:'08:00',end_time:'10:00',max_attempts:1,is_active:true});open.value=true;}
function save(){form.submit(editing.value?'put':'post',base.value+'/exam-accesses'+(editing.value?'/'+editing.value.id:''),{onSuccess:()=>open.value=false});}
const formatDate=value=>new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Bangkok'}).format(new Date(value));
</script>
<template><Head :title="'Cấp quyền thi · '+context.name"/><AppLayout><div class="page-heading"><div><h1>Ngày, ca & lượt thi {{context.name}}</h1><p>Chỉ cấp đề và tài khoản trong cùng phần thi. Thời gian UTC+7.</p></div><button @click="show()">+ Cấp quyền thi</button></div><div class="notice">Đăng nhập không tính lượt. Bắt đầu bài mới tính một lượt; tiếp tục bài đang làm không tính thêm. Thời hạn bài là thời điểm sớm hơn giữa hết thời lượng đề và hết ngày/ca.</div><div class="card"><form class="filter-row" @submit.prevent="router.get(base+'/exam-accesses',{search,date},{preserveState:true})"><input v-model="search" placeholder="Tìm tên / email" aria-label="Tìm thí sinh"/><input v-model="date" type="date" aria-label="Lọc ngày thi"/><button>Lọc</button><Link :href="base+'/exam-accesses'" class="btn secondary">Đặt lại</Link></form><div class="tablewrap"><table><thead><tr><th>Thí sinh</th><th>Đề thi</th><th>Ngày / ca</th><th>Đã dùng / tối đa</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="access in accesses.data" :key="access.id"><td>{{access.user.name}}<small class="cell-meta">{{access.user.email}}</small></td><td class="table-title">{{access.exam.title}}</td><td>{{formatDate(access.exam_date)}}<small class="cell-meta">{{access.access_mode==='session'?access.session_name+' · '+access.start_time.slice(0,5)+'–'+access.end_time.slice(0,5):'Cả ngày'}}</small></td><td>{{access.attempts_count}} / {{access.max_attempts}}<small v-for="attempt in access.attempts" :key="attempt.id" class="cell-meta">Lượt {{attempt.attempt_number}} · {{attempt.submitted_at?'Đã kết thúc':'Đã bắt đầu'}}</small></td><td><span class="pill" :class="{inactive:!access.is_active||!access.user.is_active}">{{!access.user.is_active?'Tài khoản đã khóa':access.is_active?'Được thi':'Đã thu hồi'}}</span></td><td><div class="actions"><button class="secondary" @click="show(access)">Sửa / thu hồi</button><button class="secondary" @click="action={url:base+'/exam-accesses/'+access.id,title:'Xóa quyền thi',message:'Xóa quyền thi này? Quyền đã phát sinh bài làm sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!accesses.data.length"><td colspan="6" class="empty-state">Chưa có quyền thi phù hợp trong phân hệ này.</td></tr></tbody></table></div><div class="pagination"><Link v-if="accesses.prev_page_url" :href="accesses.prev_page_url">← Trước</Link><span>Trang {{accesses.current_page}} / {{accesses.last_page}}</span><Link v-if="accesses.next_page_url" :href="accesses.next_page_url">Tiếp →</Link></div></div>
<AppModal :open="open" :title="editing?'Sửa quyền thi':'Cấp quyền thi · '+context.name" wide :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><template v-if="!editing"><p v-if="!students.length||!exams.length" class="notice">Cần tài khoản thi đang hoạt động và đề đã mở. <Link :href="base+'/users'">Tạo tài khoản</Link> · <Link :href="base+'/exams'">Quản lý đề</Link></p><div class="formgrid"><div class="field"><label for="grant-user">Tài khoản thi {{context.name}}</label><select id="grant-user" v-model="form.user_id" required><option value="" disabled>Chọn tài khoản</option><option v-for="student in students" :key="student.id" :value="student.id">{{student.name}} · {{student.email}}</option></select></div><div class="field"><label for="grant-exam">Đề đã mở</label><select id="grant-exam" v-model="form.exam_id" required><option value="" disabled>Chọn đề</option><option v-for="exam in exams" :key="exam.id" :value="exam.id">{{exam.title}} · {{exam.questions_count}} câu</option></select></div><div class="field"><label for="grant-mode">Cách cấp</label><select id="grant-mode" v-model="form.access_mode"><option value="day">Theo ngày + số lượt</option><option value="session">Theo ca + số lượt</option></select></div><div class="field"><label for="grant-date">Ngày thi</label><input id="grant-date" v-model="form.exam_date" type="date" :min="today" required/></div><template v-if="form.access_mode==='session'"><div class="field"><label for="grant-session">Tên ca</label><input id="grant-session" v-model="form.session_name" required maxlength="255"/></div><div class="field"><label for="grant-start">Giờ bắt đầu</label><input id="grant-start" v-model="form.start_time" type="time" required/></div><div class="field"><label for="grant-end">Giờ kết thúc (cùng ngày)</label><input id="grant-end" v-model="form.end_time" type="time" required/></div></template></div></template><div class="formgrid"><div class="field"><label for="grant-attempts">Tổng số lượt tối đa</label><input id="grant-attempts" v-model.number="form.max_attempts" type="number" min="1" max="100" required/></div><div v-if="editing" class="field"><label for="grant-active">Trạng thái</label><select id="grant-active" v-model="form.is_active"><option :value="true">Được phép thi</option><option :value="false">Thu hồi quyền thi</option></select></div></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing||(!editing&&(!students.length||!exams.length))">{{editing?'Lưu quyền thi':'Cấp quyền thi'}}</button></div></form></AppModal><ConfirmAction :action="action" @close="action=null"/></AppLayout></template>
